import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <int TILE, int IC_TILE, int OC_TILE>
__global__ void cute_transpose3d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ b_ptr,
    float* __restrict__ y_ptr,
    int N,
    int IC,
    int ID,
    int IH,
    int IW,
    int OC,
    int K,
    int OD,
    int OH,
    int OW,
    bool has_bias)
{
    constexpr int TILE_X = TILE;
    constexpr int TILE_Y = TILE;
    constexpr int TILE_Z = TILE / 2;
    constexpr int THREADS = TILE * TILE_Y * TILE_Z;
    const int oc_tiles = (OC + OC_TILE - 1) / OC_TILE;
    const int z_tiles = (OD + TILE_Z - 1) / TILE_Z;
    const int block_id = static_cast<int>(blockIdx.z);
    const int n = block_id / (z_tiles * oc_tiles);
    const int rem = block_id % (z_tiles * oc_tiles);
    const int oz_tile = rem / oc_tiles;
    const int oc_tile = rem % oc_tiles;
    const int oc0 = oc_tile * OC_TILE;
    if (n >= N) {
        return;
    }
    const int oz0 = oz_tile * TILE_Z;
    const int oy0 = static_cast<int>(blockIdx.y) * TILE_Y;
    const int ox0 = static_cast<int>(blockIdx.x) * TILE_X;
    auto gX = make_tensor(
        make_gmem_ptr(x_ptr),
        make_shape(N, IC, ID, IH, IW),
        make_stride(IC * ID * IH * IW,
                    ID * IH * IW,
                    IH * IW,
                    IW,
                    1));
    auto gW = make_tensor(
        make_gmem_ptr(w_ptr),
        make_shape(IC, OC, K, K, K),
        make_stride(OC * K * K * K,
                    K * K * K,
                    K * K,
                    K,
                    1));
    auto gY = make_tensor(
        make_gmem_ptr(y_ptr),
        make_shape(N, OC, OD, OH, OW),
        make_stride(OC * OD * OH * OW,
                    OD * OH * OW,
                    OH * OW,
                    OW,
                    1));
    extern __shared__ float smem[];
    const int shared_x = TILE_X + K - 1;
    const int shared_y = TILE_Y + K - 1;
    const int shared_z = TILE_Z + K - 1;
    const size_t shared_x_volume =
        static_cast<size_t>(IC_TILE) * shared_z * shared_y * shared_x;
    auto sX = make_tensor(
        make_smem_ptr(smem),
        make_shape(IC_TILE, shared_z, shared_y, shared_x),
        make_stride(shared_z * shared_y * shared_x,
                    shared_y * shared_x,
                    shared_x,
                    1));
     auto sW = make_tensor(
         make_smem_ptr(smem + shared_x_volume),
         make_shape(IC_TILE, K, K, K, OC_TILE),
         make_stride(
             K * K * K * OC_TILE,
             K * K * OC_TILE,
             K * OC_TILE,
             OC_TILE,
             1));
    const int tid = static_cast<int>(threadIdx.x);
    if (tid >= THREADS) {
        return;
    }
    const int spatial = tid;
    const int lz = spatial / (TILE_Y * TILE);
    const int rem_spatial = spatial % (TILE_Y * TILE);
    const int ly = rem_spatial / TILE;
    const int lx = rem_spatial % TILE;
    const int oz = oz0 + lz;
    const int oy = oy0 + ly;
    const int ox_thread = ox0 + lx;
    float acc0[OC_TILE];
    for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
        const int oc = oc0 + oc_local;
        acc0[oc_local] = 0.0f;
        if (has_bias && oc < OC && oz < OD && oy < OH && ox_thread < OW) {
            acc0[oc_local] = b_ptr[oc];
        }
    }
    const int shared_volume = IC_TILE * shared_z * shared_y * shared_x;
    for (int ic0 = 0; ic0 < IC; ic0 += IC_TILE) {
        for (int linear = tid; linear < shared_volume; linear += blockDim.x) {
            int t = linear;
            const int lx_s = t % shared_x;
            t /= shared_x;
            const int ly_s = t % shared_y;
            t /= shared_y;
            const int lz_s = t % shared_z;
            const int ic_local = t / shared_z;
            const int ic_global = ic0 + ic_local;
            float value = 0.0f;
            if (ic_global < IC) {
                const int iz = oz0 - (K - 1) + lz_s;
                const int iy = oy0 - (K - 1) + ly_s;
                const int ix = ox0 - (K - 1) + lx_s;
                if (iz >= 0 && iz < ID &&
                    iy >= 0 && iy < IH &&
                    ix >= 0 && ix < IW) {
                    value = gX(n, ic_global, iz, iy, ix);
                }
            }
            sX(ic_local, lz_s, ly_s, lx_s) = value;
        }
        __syncthreads();
         const int shared_weight =
             IC_TILE * K * K * K * OC_TILE;
         for (int linear = tid; linear < shared_weight; linear += blockDim.x) {
             int t = linear;
             const int oc_local = t % OC_TILE;
             t /= OC_TILE;
             const int kx = t % K;
             t /= K;
             const int ky = t % K;
             t /= K;
             const int kz = t % K;
             t /= K;
             const int ic_local = t;
             const int ic_global = ic0 + ic_local;
             const int oc_global = oc0 + oc_local;
             float value = 0.0f;
             if (ic_global < IC && oc_global < OC) {
                 value = gW(ic_global, oc_global, kz, ky, kx);
             }
             sW(ic_local, kz, ky, kx, oc_local) = value;
         }
        __syncthreads();
        const int ic_count = min(IC_TILE, IC - ic0);
        if (oz < OD && oy < OH) {
            for (int ic_local = 0; ic_local < ic_count; ++ic_local) {
                const int ic_global = ic0 + ic_local;
                for (int kz = 0; kz < K; ++kz) {
                    const int sxz = lz + (K - 1 - kz);
                    for (int ky = 0; ky < K; ++ky) {
                        const int sxy = ly + (K - 1 - ky);
                        for (int kx = 0; kx < K; ++kx) {
                            const int sxx = lx + (K - 1 - kx);
                            for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
                                const int oc = oc0 + oc_local;
                                if (oc < OC && ox_thread < OW) {
                                    const float w = sW(ic_local, kz, ky, kx, oc_local);
                                    acc0[oc_local] += sX(ic_local, sxz, sxy, sxx) * w;
                                }
                            }
                            }
                        }
                    }
                }
            }
        __syncthreads();
    }
    if (oz < OD && oy < OH) {
        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
            const int oc = oc0 + oc_local;
            if (oc < OC) {
                if (ox_thread < OW) {
                    gY(n, oc, oz, oy, ox_thread) = acc0[oc_local];
                }
            }
        }
    }
}


template <int TILE, int IC_TILE, int OC_TILE>
void launch_cute_transpose3d(
    const torch::Tensor& xc,
    const torch::Tensor& wc,
    const torch::Tensor& bc,
    torch::Tensor& yc,
    int N,
    int IC,
    int ID,
    int IH,
    int IW,
    int OC,
    int K,
    int OD,
    int OH,
    int OW,
    bool has_bias,
    cudaStream_t stream)
{
     constexpr int TILE_X = TILE;
     constexpr int TILE_Y = TILE;
     constexpr int TILE_Z = TILE / 2;
     constexpr int THREADS = TILE * TILE_Y * TILE_Z;
    const int oc_tiles = (OC + OC_TILE - 1) / OC_TILE;
    const int z_tiles = (OD + TILE_Z - 1) / TILE_Z;
    dim3 block(THREADS);
    dim3 grid(
        (OW + TILE_X - 1) / TILE_X,
        (OH + TILE_Y - 1) / TILE_Y,
        N * z_tiles * oc_tiles);
     const int shared_x = TILE_X + K - 1;
     const int shared_y = TILE_Y + K - 1;
     const int shared_z = TILE_Z + K - 1;
     const size_t smem_bytes =
         (static_cast<size_t>(IC_TILE) * shared_x * shared_y * shared_z +
          static_cast<size_t>(IC_TILE) * K * K * K * OC_TILE) * sizeof(float);
    cute_transpose3d_kernel<TILE, IC_TILE, OC_TILE>
        <<<grid, block, smem_bytes, stream>>>(
            xc.data_ptr<float>(),
            wc.data_ptr<float>(),
            has_bias ? bc.data_ptr<float>() : nullptr,
            yc.data_ptr<float>(),
            N, IC, ID, IH, IW,
            OC, K, OD, OH, OW,
            has_bias);
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(
        err == cudaSuccess,
        "CuTe transposed convolution launch failed: ",
        cudaGetErrorString(err));
}
torch::Tensor cute_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must have shape [N, IC, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape [IC, OC, K, K, K]");

    if (bias.has_value()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias->scalar_type() == at::kFloat, "bias must be float32");
        TORCH_CHECK(bias->dim() == 1, "bias must be 1D");
        TORCH_CHECK(bias->device() == x.device(),
                    "bias must be on the same CUDA device as x");
    }

    auto xc = x.contiguous();
    auto wc = weight.contiguous();

    const int N = static_cast<int>(xc.size(0));
    const int IC = static_cast<int>(xc.size(1));
    const int ID = static_cast<int>(xc.size(2));
    const int IH = static_cast<int>(xc.size(3));
    const int IW = static_cast<int>(xc.size(4));

    const int weight_ic = static_cast<int>(wc.size(0));
    const int OC = static_cast<int>(wc.size(1));
    const int K = static_cast<int>(wc.size(2));

     TORCH_CHECK(x.device() == weight.device(),
                 "x and weight must be on the same CUDA device");
    TORCH_CHECK(weight_ic == IC, "weight.size(0) must equal x.size(1)");
     TORCH_CHECK(K > 0 && wc.size(3) > 0 && wc.size(4) > 0,
                 "kernel dimensions must be positive");
     TORCH_CHECK(wc.size(2) == wc.size(3) && wc.size(2) == wc.size(4),
                 "only cubic kernels are supported");

    if (bias.has_value()) {
        TORCH_CHECK(bias->size(0) == OC, "bias size mismatch");
    }

    const int OD = ID + K - 1;
    const int OH = IH + K - 1;
    const int OW = IW + K - 1;

    auto yc = torch::empty({N, OC, OD, OH, OW}, xc.options());

    torch::Tensor bc;
    const float* b_ptr = nullptr;
    bool has_bias = false;

    if (bias.has_value()) {
        bc = bias->contiguous();
        b_ptr = bc.data_ptr<float>();
        has_bias = true;
    }

    constexpr int TILE = 8;
    constexpr int IC_TILE = 8;
     constexpr int OC_TILE = 8;
    const int device = xc.get_device();
    int max_smem = 0;
    TORCH_CHECK(
        cudaDeviceGetAttribute(
            &max_smem,
            cudaDevAttrMaxSharedMemoryPerBlock,
            device) == cudaSuccess,
        "Unable to query the device shared-memory limit");
    auto fits = [&](int tile, int ic_tile) -> bool {
         const int tile_x = tile;
         const int tile_y = tile;
         const int tile_z = tile / 2;
        const size_t bytes =
            (static_cast<size_t>(ic_tile) *
                 (tile_x + K - 1) *
                 (tile_y + K - 1) *
                 (tile_z + K - 1) +
             static_cast<size_t>(ic_tile) *
                 K * K * K * OC_TILE) * sizeof(float);
        return bytes <= static_cast<size_t>(max_smem);
    };
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (fits(8, 8)) {
         launch_cute_transpose3d<8, 8, 8>(
            xc, wc, bc, yc,
            N, IC, ID, IH, IW, OC, K, OD, OH, OW,
            has_bias, stream);
    } else if (fits(4, 4)) {
         launch_cute_transpose3d<4, 4, 8>(
            xc, wc, bc, yc,
            N, IC, ID, IH, IW, OC, K, OD, OH, OW,
            has_bias, stream);
    } else if (fits(2, 4)) {
         launch_cute_transpose3d<2, 4, 8>(
            xc, wc, bc, yc,
            N, IC, ID, IH, IW, OC, K, OD, OH, OW,
            has_bias, stream);
    } else if (fits(2, 1)) {
         launch_cute_transpose3d<2, 1, 8>(
            xc, wc, bc, yc,
            N, IC, ID, IH, IW, OC, K, OD, OH, OW,
            has_bias, stream);
    } else {
        TORCH_CHECK(
            false,
            "Kernel size is too large for the available shared memory");
    }

    return yc;
}
"""


cute_ext = load_inline(
    name="cute_transpose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_transpose3d"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        if stride != 1:
            raise ValueError("ModelNew supports stride=1")
        if padding != 0:
            raise ValueError("ModelNew supports padding=0")
        if output_padding != 0:
            raise ValueError("ModelNew supports output_padding=0")
        if dilation != 1:
            raise ValueError("ModelNew supports dilation=1")
        if groups != 1:
            raise ValueError("ModelNew supports groups=1")

        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            (kernel_size, kernel_size, kernel_size),
            stride=1,
            padding=0,
            output_padding=0,
            dilation=1,
            groups=1,
            bias=bias,
        )
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_transpose3d(
            x,
            self.conv_transpose3d.weight,
            self.conv_transpose3d.bias,
        )

