    }

    const int OD = ID + K - 1;
    const int OH = IH + K - 1;
    const int OW = IW + K - 1;

    auto yc = torch::empty({N, OC, OD, OH, OW}, xc.options());

    torch::Tensor bc;
    const float* b_ptr = nullptr;
