                if (ox0_thread < OW) {
                    gY(n, oc, oz, oy, ox0_thread) = acc0[oc_local];
                }
                if (ox1_thread < OW) {
                    gY(n, oc, oz, oy, ox1_thread) = acc1[oc_local];
                }
            }
        }
    }
